// Subject: Share your experience at {_targetName}

import {
  Body,
  Button,
  Container,
  Head,
  Html,
  Preview,
  Section,
  Tailwind,
  Text,
} from "jsx-email";

import { emailAsset } from "@/components/email/email-assets";
import { airbnbTheme } from "@/components/email/theme-airbnb";

interface Props {
  _logoUrl?: string;
  actorName?: string;
  _actorAvatarUrl?: string;
  _action?: string;
  _targetName?: string;
  ctaLabel?: string;
  ctaHref?: string;
  _productName?: string;
}

export const NotificationAirbnb = ({
  _logoUrl,
  actorName = "Host",
  _actorAvatarUrl,
  _action = "completed their stay",
  _targetName = "your place",
  ctaLabel = "Leave a Review",
  ctaHref = "#",
  _productName = "Airbnb",
}: Props) => {
  void _logoUrl;
  void _actorAvatarUrl;
  void _action;
  void _productName;

  return (
    <Html>
      <Head />
      <Preview>Share your experience</Preview>
      <Tailwind>
        <Body
          style={{
            backgroundColor: airbnbTheme.colorBackground,
            fontFamily: airbnbTheme.fontFamily,
            margin: 0,
          }}
        >
          <Container
            style={{ maxWidth: airbnbTheme.containerWidth, padding: "32px 0" }}
          >
            <Section style={{ paddingTop: airbnbTheme.spacingXl }}>
              <Text
                style={{
                  color: airbnbTheme.colorText,
                  fontSize: airbnbTheme.fontSizeXl,
                  fontWeight: airbnbTheme.fontWeightMedium,
                  marginBottom: airbnbTheme.spacingBase,
                }}
              >
                How was your trip?
              </Text>
              <Text
                style={{
                  color: airbnbTheme.colorTextMuted,
                  fontSize: airbnbTheme.fontSizeBase,
                  lineHeight: airbnbTheme.lineHeightBase,
                  marginBottom: airbnbTheme.spacingBase,
                }}
              >
                {actorName} recently stayed at {_targetName} and we&apos;d love
                to hear about their experience.
              </Text>
              <Text
                style={{
                  color: airbnbTheme.colorTextMuted,
                  fontSize: airbnbTheme.fontSizeBase,
                  lineHeight: airbnbTheme.lineHeightBase,
                  marginBottom: airbnbTheme.spacingBase,
                }}
              >
                Your review helps other travelers and supports your host.
              </Text>
            </Section>

            {ctaLabel && ctaHref && (
              <Section style={{ paddingTop: airbnbTheme.spacingLg }}>
                <Button
                  href={ctaHref}
                  width={160}
                  height={40}
                  style={{
                    backgroundColor: airbnbTheme.button.primary.backgroundColor,
                    borderRadius: airbnbTheme.button.primary.borderRadius,
                    color: airbnbTheme.button.primary.color,
                    display: "inline-block",
                    fontSize: airbnbTheme.button.primary.fontSize,
                    fontWeight: airbnbTheme.button.primary.fontWeight,
                    height: "auto",
                    paddingBottom: airbnbTheme.button.primary.paddingY,
                    paddingLeft: airbnbTheme.button.primary.paddingX,
                    paddingRight: airbnbTheme.button.primary.paddingX,
                    paddingTop: airbnbTheme.button.primary.paddingY,
                    textDecoration: "none",
                    width: "auto",
                  }}
                >
                  {ctaLabel}
                </Button>
              </Section>
            )}
          </Container>
        </Body>
      </Tailwind>
    </Html>
  );
};

NotificationAirbnb.PreviewProps = {
  _action: "completed their stay",
  _actorAvatarUrl: emailAsset("avatars/avatar-1.jpg"),
  _logoUrl: emailAsset("logos/logo-emailcn.png"),
  _productName: "Airbnb",
  _targetName: "your place",
  actorName: "John",
  ctaHref: "https://airbnb.com/reviews",
  ctaLabel: "Leave a Review",
} satisfies Props;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
